// Total PV Energy (lifetime)
// 96: historyPV PowerWh Low (0.1kWh)
// 97: historyPV PowerWh High (0.1kWh)

msg.baseAddr = 96;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 96,
    quantity: 2
};
return msg;

// Day PV and MPPT Voltage/Current
// 108: Day PV PowerWh (0.1kWh)
// 109: DC voltage 1 (0.1V)
// 110: DC current 1 (0.1A)
// 111: DC voltage 2 (0.1V)
// 112: DC current 2 (0.1A)
// 113: DC voltage 3 (0.1V)
// 114: DC current 3 (0.1A)
// 115: DC voltage 4 (0.1V)
// 116: DC current 4 (0.1A)

msg.baseAddr = 108;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 108,
    quantity: 9
};
return msg;

// MPPT Power
// 186: PV1 input power (1W)
// 187: PV2 input power (1W)
// 188: PV3 input power (1W)
// 189: PV4 input power (1W)

msg.baseAddr = 186;
msg.payload = {
    fc: 3,
    unitid: 1,
    address: 186,
    quantity: 4
};
return msg;

// Build PvDeviceState from multiple Modbus reads.

let raw = msg.payload;
let data = raw;
if (data && Array.isArray(data.data)) {
    data = data.data;
}

if (typeof raw === "string" || !Array.isArray(data)) {
    return null;
}

let baseAddr = msg.baseAddr;
if (typeof baseAddr !== "number") {
    baseAddr = (msg.modbusRequest && msg.modbusRequest.address);
}
if (typeof baseAddr !== "number") {
    node.warn("PvDeviceState: missing base address");
    return null;
}

// Helper: combine two 16-bit words to 32-bit unsigned
function u32(low, high) {
    return ((high & 0xFFFF) << 16) | (low & 0xFFFF);
}

// ---- Store partials ----

// Total Energy 96-97
if (baseAddr === 96) {
    const totalLow = data[0] || 0;   // 96
    const totalHigh = data[1] || 0;  // 97

    const totalKWh = Math.round(u32(totalLow, totalHigh) * 0.1 * 10) / 10;

    flow.set("pvds_part_total_energy", {
        totalPvEnergyKWh: totalKWh
    });
}

// Daily/MPPT V/I 108-116
else if (baseAddr === 108) {
    const dailyRaw = data[0] || 0;   // 108: Day PV (0.1kWh)
    const v1 = data[1] || 0;         // 109: DC voltage 1 (0.1V)
    const i1 = data[2] || 0;         // 110: DC current 1 (0.1A)
    const v2 = data[3] || 0;         // 111: DC voltage 2 (0.1V)
    const i2 = data[4] || 0;         // 112: DC current 2 (0.1A)
    const v3 = data[5] || 0;         // 113: DC voltage 3 (0.1V)
    const i3 = data[6] || 0;         // 114: DC current 3 (0.1A)
    const v4 = data[7] || 0;         // 115: DC voltage 4 (0.1V)
    const i4 = data[8] || 0;         // 116: DC current 4 (0.1A)

    flow.set("pvds_part_daily_voltage", {
        todayPvEnergyKWh: Math.round(dailyRaw * 0.1 * 10) / 10,
        mppt1: { voltageV: Math.round(v1 * 0.1 * 10) / 10, currentA: Math.round(i1 * 0.1 * 10) / 10 },
        mppt2: { voltageV: Math.round(v2 * 0.1 * 10) / 10, currentA: Math.round(i2 * 0.1 * 10) / 10 },
        mppt3: { voltageV: Math.round(v3 * 0.1 * 10) / 10, currentA: Math.round(i3 * 0.1 * 10) / 10 },
        mppt4: { voltageV: Math.round(v4 * 0.1 * 10) / 10, currentA: Math.round(i4 * 0.1 * 10) / 10 }
    });
}

// MPPT Power 186-189
else if (baseAddr === 186) {
    const p1 = data[0] || 0;  // 186: PV1 power (1W)
    const p2 = data[1] || 0;  // 187: PV2 power (1W)
    const p3 = data[2] || 0;  // 188: PV3 power (1W)
    const p4 = data[3] || 0;  // 189: PV4 power (1W)

    const totalPower = p1 + p2 + p3 + p4;

    flow.set("pvds_part_power", {
        totalPvPowerW: totalPower,
        mppt1PowerW: p1,
        mppt2PowerW: p2,
        mppt3PowerW: p3,
        mppt4PowerW: p4
    });
}
else {
    return null;
}

// ---- Try to assemble ----

const totalEnergyPart = flow.get("pvds_part_total_energy");
const dailyVoltagePart = flow.get("pvds_part_daily_voltage");
const powerPart = flow.get("pvds_part_power");

if (!totalEnergyPart || !dailyVoltagePart || !powerPart) {
    return null;
}

const deviceId = msg.deviceId
    || global.get("DEVICE_ID")
    || env.get("DEVICE_ID")
    || "EC100-DEV-001";

// Helper to determine if MPPT is active
function isMpptActive(powerW, voltageV) {
    return powerW > 0 || voltageV > 0;
}

const state = {
    kind: "PvDeviceState",
    timestampUtc: new Date().toISOString(),
    version: 1,
    DeviceId: deviceId,

    totalPvPowerW: powerPart.totalPvPowerW,
    todayPvEnergyKWh: dailyVoltagePart.todayPvEnergyKWh,
    totalPvEnergyKWh: totalEnergyPart.totalPvEnergyKWh,

    mppt: [
        {
            pvChannelId: 1,
            isActive: isMpptActive(powerPart.mppt1PowerW, dailyVoltagePart.mppt1.voltageV),
            dcVoltageV: dailyVoltagePart.mppt1.voltageV,
            dcCurrentA: dailyVoltagePart.mppt1.currentA,
            inputPowerW: powerPart.mppt1PowerW,
            todayEnergyKWh: null,
            totalEnergyKWh: null
        },
        {
            pvChannelId: 2,
            isActive: isMpptActive(powerPart.mppt2PowerW, dailyVoltagePart.mppt2.voltageV),
            dcVoltageV: dailyVoltagePart.mppt2.voltageV,
            dcCurrentA: dailyVoltagePart.mppt2.currentA,
            inputPowerW: powerPart.mppt2PowerW,
            todayEnergyKWh: null,
            totalEnergyKWh: null
        },
        {
            pvChannelId: 3,
            isActive: isMpptActive(powerPart.mppt3PowerW, dailyVoltagePart.mppt3.voltageV),
            dcVoltageV: dailyVoltagePart.mppt3.voltageV,
            dcCurrentA: dailyVoltagePart.mppt3.currentA,
            inputPowerW: powerPart.mppt3PowerW,
            todayEnergyKWh: null,
            totalEnergyKWh: null
        },
        {
            pvChannelId: 4,
            isActive: isMpptActive(powerPart.mppt4PowerW, dailyVoltagePart.mppt4.voltageV),
            dcVoltageV: dailyVoltagePart.mppt4.voltageV,
            dcCurrentA: dailyVoltagePart.mppt4.currentA,
            inputPowerW: powerPart.mppt4PowerW,
            todayEnergyKWh: null,
            totalEnergyKWh: null
        }
    ]
};

// Clear partials
flow.set("pvds_part_total_energy", null);
flow.set("pvds_part_daily_voltage", null);
flow.set("pvds_part_power", null);

flow.set("pvDeviceStateSnapshot", state);

msg.payload = state;
msg.state = state;
return msg;

// Only handle messages that came from RPC
if (!msg.rpcResponseTopic) {
    return null;
}

const state = msg.state || msg.payload;

msg.payload = state;
msg.topic = msg.rpcResponseTopic;

return msg;
